package dev.navifold.player;
import android.content.*;import android.graphics.*;import android.os.*;import org.json.*;
public final class ConvenienceProbe extends BroadcastReceiver {
 static int fullRefreshes,partialRefreshes;static androidx.recyclerview.widget.RecyclerView.Adapter observed;static final androidx.recyclerview.widget.RecyclerView.AdapterDataObserver observer=new androidx.recyclerview.widget.RecyclerView.AdapterDataObserver(){public void onChanged(){fullRefreshes++;}public void onItemRangeChanged(int start,int count){partialRefreshes+=count;}};
 public void onReceive(Context receiver,Intent intent){Context c=receiver.getApplicationContext();String action=intent.getStringExtra("action");JSONObject proof=new JSONObject();try{
 if("settingsCache".equals(action)){AppSettings a=AppSettings.cached(c),b=AppSettings.cached(c);int original=a.ringCompactDp;AppSettings.preferences(c).edit().putInt("ringCompactDp",original==96?95:original+1).apply();AppSettings after=AppSettings.cached(c);proof.put("reused",a==b).put("invalidated",after!=a&&after.ringCompactDp!=original);AppSettings.preferences(c).edit().putInt("ringCompactDp",original).apply();}
 if(("observeQueue".equals(action)||"queueMetrics".equals(action))&&android.os.Build.VERSION.SDK_INT>=29){if("observeQueue".equals(action)){if(observed!=null)observed.unregisterAdapterDataObserver(observer);observed=null;for(android.view.View root:android.view.inspector.WindowInspector.getGlobalWindowViews())findQueue(root);fullRefreshes=partialRefreshes=0;if(observed!=null)observed.registerAdapterDataObserver(observer);}proof.put("observing",observed!=null).put("full",fullRefreshes).put("partialRows",partialRefreshes);}
 if("round".equals(action)){MainActivity.SquareImage view=new MainActivity.SquareImage(c);view.setImageDrawable(new android.graphics.drawable.ColorDrawable(Color.WHITE));view.layout(0,0,120,120);Bitmap bitmap=Bitmap.createBitmap(120,120,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(Color.GREEN);view.draw(canvas);proof.put("cornerClipped",bitmap.getPixel(1,1)==Color.GREEN).put("centerVisible",bitmap.getPixel(60,60)==Color.WHITE);}
 if("busy".equals(action)){SmartPlayback.settings(c).edit().putBoolean("autoplay",true).putBoolean("refillBusy",true).apply();SmartStatus.record(c,"다음 곡 추천 중");proof.put("busy",true);}
 if("done".equals(action)){SmartPlayback.settings(c).edit().putBoolean("refillBusy",false).apply();SmartStatus.record(c,"LOCAL · 10곡 추가");proof.put("history",SmartStatus.history(c));}
 if("metered".equals(action)){NetworkUsage n=NetworkUsage.get(c);n.metered=true;n.cellular=true;n.connected=true;n.network="모바일 · QA";n.prefs.edit().putBoolean("economy",true).apply();Api api=new Api("http://127.0.0.1:18765","demo","demo");androidx.media3.common.MediaItem item=PlaybackItems.make(api,new JSONObject().put("id","s000-0").put("duration",120),true,320,false);proof.put("meteredOriginalConverted",item.mediaMetadata.extras.getBoolean("transcoded")).put("format",item.localConfiguration.uri.getQueryParameter("format")).put("bitrate",item.localConfiguration.uri.getQueryParameter("maxBitRate"));n.metered=false;proof.put("wifiKeepsOriginal",NetworkUsage.original(true));n.metered=true;}
 if("ui".equals(action)&&android.os.Build.VERSION.SDK_INT>=29){for(android.view.View root:android.view.inspector.WindowInspector.getGlobalWindowViews()){android.view.View note=root.findViewWithTag("smart-note"),bar=root.findViewWithTag("smart-progress");if(note instanceof android.widget.TextView)proof.put("note",((android.widget.TextView)note).getText());if(bar!=null)proof.put("progressVisibility",bar.getVisibility());}}
 if("usage".equals(action)){NetworkUsage n=NetworkUsage.get(c);n.sample(true);proof.put("rx",n.prefs.getLong("rx",0)).put("tx",n.prefs.getLong("tx",0)).put("summary",n.summary());}
 try(java.io.FileOutputStream out=c.openFileOutput("convenience-proof.json",0)){out.write(proof.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}setResultData(proof.toString());
 }catch(Exception e){setResultData("failed "+e.getClass().getSimpleName());}}
 static void findQueue(android.view.View view){if(view instanceof androidx.recyclerview.widget.RecyclerView){observed=((androidx.recyclerview.widget.RecyclerView)view).getAdapter();return;}if(view instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)view;for(int n=0;n<g.getChildCount();n++)findQueue(g.getChildAt(n));}}

}
